//! Embed the Windows shell icon into `fast-diff-viewer.exe`.
//!
//! `winresource` wraps the platform's resource compiler (`rc.exe` on
//! MSVC, `windres` on GNU) and generates a minimal `.rc` pointing at
//! our multi-resolution `.ico`, so Cargo builds embed the icon as a
//! normal PE `IDI_ICON1` resource without a hand-written `.rc`.
//!
//! The icon source of truth is `assets/icon/fast-diff-viewer.svg`; the
//! committed `.ico` is regenerated by the Cargo example at
//! `scripts/gen_icon.rs`:
//! `cargo run --example gen_icon --release`.
//!
//! Cargo uses one build script per package. This script checks the target OS:
//! Windows targets embed the PE icon, while Ubuntu and macOS targets stay
//! independent of Windows resource tooling.

fn main() {
    // The resource embeds the icon and Cargo package version.
    println!("cargo:rerun-if-changed=assets/icon/fast-diff-viewer.ico");
    println!("cargo:rerun-if-changed=Cargo.toml");
    println!("cargo:rerun-if-changed=build.rs");

    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        embed_windows_icon();
    }
}

#[cfg(windows)]
fn embed_windows_icon() {
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon/fast-diff-viewer.ico");
    if let Err(e) = res.compile() {
        // Fail the build loudly; a missing icon resource would
        // silently ship the generic Windows executable icon,
        // which defeats the purpose of embedding it.
        panic!("winresource failed to embed fast-diff-viewer.ico: {e}");
    }
}

#[cfg(not(windows))]
fn embed_windows_icon() {
    panic!("Windows target resource embedding requires a Windows host build");
}
